<?php $title = 'ثبت سند دستی'; ?>
<div class="card"><h2>سند جدید</h2><form method="post" action="<?= e(base_url('accounting/journal/save')) ?>" data-autosave="journal"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><div class="grid"><div class="col-4"><label>شماره سند</label><input name="entry_no" value="<?= e($entryNo) ?>" required></div><div class="col-4"><label>تاریخ</label><input type="date" name="entry_date" value="<?= e(date('Y-m-d')) ?>" required></div><div class="col-4"><label>شرح</label><input name="description"></div></div><div class="table-wrap"><table class="table"><tr><th>حساب</th><th>بدهکار</th><th>بستانکار</th><th>طرف حساب</th><th>بانک</th><th>شرح ردیف</th></tr><?php for($n=0;$n<6;$n++): ?><tr><td><select name="lines[<?= $n ?>][account_id]"><option value="">-</option><?php foreach($accounts as $a): ?><option value="<?= e($a['id']) ?>"><?= e($a['code'].' - '.$a['name']) ?></option><?php endforeach; ?></select></td><td><input type="number" step="0.01" name="lines[<?= $n ?>][debit]" value="0"></td><td><input type="number" step="0.01" name="lines[<?= $n ?>][credit]" value="0"></td><td><select name="lines[<?= $n ?>][party_type]"><option value="">-</option><option value="customer">مشتری</option><option value="supplier">تامین‌کننده</option></select><input name="lines[<?= $n ?>][party_id]" placeholder="شناسه طرف حساب"></td><td><select name="lines[<?= $n ?>][bank_account_id]"><option value="">-</option><?php foreach($banks as $b): ?><option value="<?= e($b['id']) ?>"><?= e($b['name']) ?></option><?php endforeach; ?></select></td><td><input name="lines[<?= $n ?>][memo]"></td></tr><?php endfor; ?></table></div><button class="btn">ثبت سند</button></form></div>
<div class="card"><h2>آخرین اسناد</h2><div class="table-wrap"><table class="table"><tr><th>تاریخ</th><th>شماره</th><th>شرح</th><th>بدهکار</th><th>بستانکار</th><th>منبع</th></tr><?php foreach($rows as $r): ?><tr><td><?= e(jalali_like_date($r['entry_date'])) ?></td><td><?= e($r['entry_no']) ?></td><td><?= e($r['description']) ?></td><td><?= e(number_format((float)$r['debit'])) ?></td><td><?= e(number_format((float)$r['credit'])) ?></td><td><?= e($r['source_type']) ?></td></tr><?php endforeach; ?></table></div></div>
